h":false},{"id":"r7c2","row":7,"col":2,"isCrate":false,"isFish":false},{"id":"r7c3","row":7,"col":3,"isCrate":false,"isFish":false},{"id":"r7c4","row":7,"col":4,"isCrate":false,"isFish":false},{"id":"r7c5","row":7,"col":5,"isCrate":false,"isFish":false},{"id":"r7c6","row":7,"col":6,"isCrate":false,"isFish":false},{"id":"r7c7","row":7,"col":7,"isCrate":false,"isFish":false}]"}},{"id":"playerNameVar","type":"Variable2","label":"Player name, app-wide","x":40,"y":120,"parameters":{"name":"playerName"}},{"id":"catColVar-2","type":"Variable2","label":"Cat column","x":40,"y":200,"parameters":{"name":"catCol","value":1}},{"id":"catRowVar-2","type":"Variable2","label":"Cat row","x":40,"y":280,"parameters":{"name":"catRow","value":7}},{"id":"dogColVar-2","type":"Variable2","label":"Dog column","x":40,"y":360,"parameters":{"name":"dogCol","value":4}},{"id":"dogRowVar-2","type":"Variable2","label":"Dog row","x":40,"y":440,"parameters":{"name":"dogRow","value":4}},{"id":"movesVar","type":"Variable2","label":"Move count","x":40,"y":520,"parameters":{"name":"moves","value":0}},{"id":"messageVar","type":"Variable2","label":"Message line","x":40,"y":600,"parameters":{"name":"message","value":""}},{"id":"gameOverVar","type":"Variable2","label":"Round over","x":40,"y":680,"parameters":{"name":"gameOver","value":false}},{"id":"tallyWonVar","type":"Variable2","label":"Tally wins","x":40,"y":760,"parameters":{"name":"tallyWon","value":0}},{"id":"tallyLostVar","type":"Variable2","label":"Tally losses","x":40,"y":840,"parameters":{"name":"tallyLost","value":0}},{"id":"movesFormat","type":"String Format","label":"Moves line text","x":320,"y":120,"parameters":{"format":"Moves: {moves}"}},{"id":"tallyFormat","type":"String Format","label":"Tally line text","x":320,"y":200,"parameters":{"format":"Won {won} · Lost {lost}"}},{"id":"gameStep","type":"JavaScriptFunction","label":"One tap on the board: validate, move Le Chonk, step the dog, end the round","x":600,"y":40,"parameters":{"functionScript":"if (Inputs.col === undefined || Inputs.row === undefined) return;

const CRATES = [[2, 2], [6, 2], [4, 3], [2, 5], [4, 5], [6, 6]];
const FISH_COL = 7;
const FISH_ROW = 1;

const isCrate = (col, row) => CRATES.some((c) => c[0] === col && c[1] === row);

const saveTally = (won, lost) => {
  localStorage.setItem("lechonk_tally", JSON.stringify({ won: won, lost: lost }));
};

// One step towards Le Chonk: along the axis with the bigger gap (across when
// the gaps are equal), the other axis when that square is a crate or the gap
// is 0, staying put when both are blocked.
const dogStep = (fromCol, fromRow, toCol, toRow) => {
  const dCol = toCol - fromCol;
  const dRow = toRow - fromRow;
  const axes = Math.abs(dCol) >= Math.abs(dRow) ? ["across", "updown"] : ["updown", "across"];
  for (const axis of axes) {
    if (axis === "across" && dCol !== 0) {
      const nextCol = fromCol + (dCol > 0 ? 1 : -1);
      if (!isCrate(nextCol, fromRow)) return [nextCol, fromRow];
    }
    if (axis === "updown" && dRow !== 0) {
      const nextRow = fromRow + (dRow > 0 ? 1 : -1);
      if (!isCrate(fromCol, nextRow)) return [fromCol, nextRow];
    }
  }
  return [fromCol, fromRow];
};

let catCol = Inputs.catCol;
let catRow = Inputs.catRow;
let dogCol = Inputs.dogCol;
let dogRow = Inputs.dogRow;
let moves = Inputs.moves;
let message = Inputs.message;
let gameOver = Inputs.gameOver;
let tallyWon = Inputs.tallyWon;
let tallyLost = Inputs.tallyLost;

if (!gameOver) {
  const tapCol = Inputs.col;
  const tapRow = Inputs.row;
  const dCol = tapCol - catCol;
  const dRow = tapRow - catRow;
  const onBoard = tapCol >= 1 && tapCol <= 7 && tapRow >= 1 && tapRow <= 7;
  const nextToCat = Math.abs(dCol) + Math.abs(dRow) === 1;
  const last = JSON.parse(sessionStorage.getItem("lechonk_last_move") || "null");
  const now = Date.now();
  const slideCol = catCol + (last ? last.dCol : 0);
  const slideRow = catRow + (last ? last.dRow : 0);
  const slides = last && dCol === 0 && dRow === 0 && now - last.at < 700 &&
    slideCol >= 1 && slideCol <= 7 && slideRow >= 1 && slideRow <= 7 && !isCrate(slideCol, slideRow) &&
    !(slideCol === dogCol && slideRow === dogRow);
  sessionStorage.removeItem("lechonk_last_move");
  if (slides) {
    catCol = slideCol;
    catRow = slideRow;
    moves = moves + 1;
    message = "";
    if (catCol === FISH_COL && catRow === FISH_ROW) {
      gameOver = true;
      message = "Le Chonk got the fish! 🐟";
      tallyWon = tallyWon + 1;
      saveTally(tallyWon, tallyLost);
    }
  } else if (nextToCat && onBoard && !isCrate(tapCol, tapRow)) {
    sessionStorage.setItem("lechonk_last_move", JSON.stringify({ dCol: dCol, dRow: dRow, at: now }));
    catCol = tapCol;
    catRow = tapRow;
    moves = moves + 1;
    message = "";
    if (catCol === FISH_COL && catRow === FISH_ROW) {
      gameOver = true;
      message = "Le Chonk got the fish! 🐟";
      tallyWon = tallyWon + 1;
      saveTally(tallyWon, tallyLost);
    } else if (catCol === dogCol && catRow === dogRow) {
      gameOver = true;
      message = "Caught! The dog wins.";
      tallyLost = tallyLost + 1;
      saveTally(tallyWon, tallyLost);
    } else if (!Inputs.qaFrozen) {
      // The dog's answer: one step per move.
      for (let i = 0; i <= 1 && !gameOver; i++) {
        const next = dogStep(dogCol, dogRow, catCol, catRow);
        dogCol = next[0];
        dogRow = next[1];
        if (dogCol === catCol && dogRow === catRow) {
          gameOver = true;
          message = "Caught! The dog wins.";
          tallyLost = tallyLost + 1;
          saveTally(tallyWon, tallyLost);
        }
      }
    }
  } else {
    message = "Le Chonk can only move one square";
  }
}

Outputs.catCol = catCol;
Outputs.catRow = catRow;
Outputs.dogCol = dogCol;
Outputs.dogRow = dogRow;
Outputs.moves = moves;
Outputs.message = message;
Outputs.gameOver = gameOver;
